SET NOCOUNT ON;
GO
IF DB_NAME() NOT IN (N'FastGuyDB',N'FastGuyDB_Inventory052_Test') THROW 51000,'052 validation target database is not approved',1;
IF OBJECT_ID(N'dbo.SchemaMigrationHistory',N'U') IS NULL OR NOT EXISTS(SELECT 1 FROM dbo.SchemaMigrationHistory WHERE migration_id = '052_ingredient_inventory_phase_1') THROW 51000,'052 validation failed: migration history missing',1;
IF EXISTS(SELECT 1 FROM (VALUES(N'InventoryItem'),(N'VariantInventoryItem'),(N'Recipe'),(N'RecipeItem'),(N'InventoryReservation'),(N'InventoryReservationItem'),(N'InventoryTransaction'),(N'InventoryReservationLegacyHistory')) x(name) WHERE OBJECT_ID(N'dbo.'+x.name,N'U') IS NULL) THROW 51000,'052 validation failed: required table missing',1;
IF COL_LENGTH('dbo.ProductVariant', 'inventory_mode') IS NULL THROW 51000, '052 validation failed: inventory_mode missing', 1;
IF COL_LENGTH(N'dbo.InventoryReservation',N'variant_id') IS NOT NULL OR COL_LENGTH(N'dbo.InventoryReservation',N'quantity') IS NOT NULL OR COL_LENGTH(N'dbo.InventoryTransaction',N'variant_id') IS NOT NULL THROW 51000,'052 validation failed: legacy column remains',1;
DECLARE @columns TABLE(table_name sysname,column_name sysname,type_name sysname,max_length smallint,precision tinyint,scale tinyint,is_nullable bit);
